// Generated from the Yale Bright Star Catalogue, 5th revised ed. (Hoffleit & Warren 1991),
// CDS catalogue V/50: every star visible to the naked eye (V <= 6.5), 9096 stars.
// 8 bytes per star, little-endian: ecliptic longitude u16 (0..2pi), ecliptic latitude u16
// (-pi/2..pi/2), parallax u16 in milliarcseconds (0 = unknown, treated as far away),
// V magnitude u8 = (V + 2) * 25, B-V colour index u8 = (B-V + 0.5) * 100.
export const STAR_COUNT = 9096;
export const STAR_DATA = '';
